create extension if not exists pgcrypto;
create type user_role as enum ('ADMIN','RRHH','OPERACIONES','SUPERVISOR','GUARDIA');
create type attendance_type as enum ('ENTRADA','SALIDA','RELEVO_ENTREGA','RELEVO_RECEPCION');
create table profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role user_role not null default 'GUARDIA',active boolean not null default true,created_at timestamptz not null default now());
create table clients(id uuid primary key default gen_random_uuid(),name text not null,active boolean not null default true,created_at timestamptz not null default now());
create table sites(id uuid primary key default gen_random_uuid(),client_id uuid not null references clients(id),name text not null,address text,latitude double precision,longitude double precision,geofence_radius_m integer not null default 100 check(geofence_radius_m between 20 and 2000),active boolean not null default true);
create table guard_posts(id uuid primary key default gen_random_uuid(),site_id uuid not null references sites(id),name text not null,coverage_hours integer not null check(coverage_hours in (8,12,24)),active boolean not null default true);
create table shifts(id uuid primary key default gen_random_uuid(),guard_post_id uuid not null references guard_posts(id),guard_id uuid references profiles(id),starts_at timestamptz not null,ends_at timestamptz not null,status text not null default 'PROGRAMADO',created_at timestamptz not null default now(),check(ends_at>starts_at));
create table attendance(id uuid primary key default gen_random_uuid(),shift_id uuid not null references shifts(id),guard_id uuid not null references profiles(id),type attendance_type not null,server_time timestamptz not null default now(),latitude double precision,longitude double precision,gps_accuracy double precision,inside_geofence boolean,photo_url text,device_id text,created_at timestamptz not null default now());
create table incidents(id uuid primary key default gen_random_uuid(),shift_id uuid references shifts(id),guard_id uuid not null references profiles(id),category text,description text not null,latitude double precision,longitude double precision,photo_url text,created_at timestamptz not null default now());
create table audit_log(id bigint generated always as identity primary key,actor_id uuid references profiles(id),entity text not null,entity_id text,action text not null,old_value jsonb,new_value jsonb,reason text,created_at timestamptz not null default now());
alter table profiles enable row level security; alter table clients enable row level security; alter table sites enable row level security; alter table guard_posts enable row level security; alter table shifts enable row level security; alter table attendance enable row level security; alter table incidents enable row level security;
